    "id": "them2026-foren-radiochaos",
    "title": "- Radio Chaos",
    "category": "Foren",
    "difficulty": "Medium",
    "points": 0,
    "date": "2026-06-08",
    "author": "rhnataiet23-art",
    "ctfName": "THEM 2026",
