        "code": "tshark -r call.pcap \\\n  -Y \"ip.src==192.168.1.100 && udp.srcport==10000 && udp.dstport==20000\" \\\n  -T fields -e data.data | awk '{print substr($0,25)}' | xxd -r -p > audio_payload.bin"
