    "id": "tjcsc-rev-rotated",
    "title": "- rev/rotated",
    "category": "Reverse",
    "difficulty": "Medium",
    "points": 0,
    "date": "2026-06-08",
    "author": "rhnataiet23-art",
    "ctfName": "TJCSC",
